import React from 'react';
import { useQuiz } from '../context/QuizContext';
import { getAvailableTopics } from '../services/aiService';

const TopicSelectionScreen = () => {
  const { actions } = useQuiz();
  const topics = getAvailableTopics();

  const handleTopicSelect = (topic) => {
    actions.selectTopic(topic);
  };

  return (
    <div className="card">
      <h1 className="title">AI Knowledge Quiz</h1>
      <p className="subtitle">Choose a topic to test your knowledge with AI-generated questions</p>
      
      <div className="topic-grid">
        {topics.map((topic) => (
          <button
            key={topic.id}
            className="topic-card"
            onClick={() => handleTopicSelect(topic)}
          >
            <div style={{ fontSize: '2rem', marginBottom: '10px' }}>
              {topic.id === 'Wellness' && '🏃‍♀️'}
              {topic.id === 'Tech Trends' && '💻'}
              {topic.id === 'Science' && '🔬'}
            </div>
            <div style={{ fontWeight: 'bold', marginBottom: '5px' }}>
              {topic.name}
            </div>
            <div style={{ fontSize: '0.9rem', opacity: 0.9 }}>
              {topic.description}
            </div>
          </button>
        ))}
      </div>
    </div>
  );
};

export default TopicSelectionScreen;
